private theorem coeff_mul_atom (q : ℚ) (e f : ℕ) (M : Law) (σ : FactorType) :
    coeffAt q (lawMul (lawAtom e f) M) σ =
      if (e, f) ∈ σ then coeffAt q M (σ.erase (e, f)) else 0

private theorem coeff_map_add (q : ℚ) (z : FactorType × Expr) (M : Law) (σ : FactorType) :
    coeffAt q (M.map fun w ↦ (z.1 + w.1, Expr.mul z.2 w.2)) σ =
      if z.1 ≤ σ then z.2.eval q * coeffAt q M (σ - z.1) else 0

private theorem coeff_mul_of_mem (q : ℚ) (L M : Law) (σ : FactorType) (S : Finset FactorType)
    (hS : ∀ z ∈ L, z.1 ∈ S) : coeffAt q (lawMul L M) σ =
      ∑ τ ∈ S, if τ ≤ σ then coeffAt q L τ * coeffAt q M (σ - τ) else 0

private theorem coeff_mul (q : ℚ) (L M : Law) (S : Finset FactorType)
    (hS : ∀ τ ∉ S, coeffAt q L τ = 0) (σ : FactorType) : coeffAt q (lawMul L M) σ =
      ∑ τ ∈ S, if τ ≤ σ then coeffAt q L τ * coeffAt q M (σ - τ) else 0

private theorem shiftedCoeff_mul (q : ℚ) (L M : Law) (τ σ : FactorType) :
    shiftedCoeff q (lawMul L M) τ σ =
      (L.map fun z ↦ z.2.eval q * shiftedCoeff q M (τ + z.1) σ).sum

private theorem list_sum_comm {α β : Type} (l : List α) (m : List β) (f : α → β → ℚ) :
    (l.map fun a ↦ (m.map fun b ↦ f a b).sum).sum =
      (m.map fun b ↦ (l.map fun a ↦ f a b).sum).sum

private theorem flatMap_replicate_eq {α β : Type} (l : List α) (x₀ : α) (g : α → β) (f : α → ℕ)
    (hf : ∀ x, x ≠ x₀ → f x = 0) (hnd : l.Nodup) (hm : x₀ ∈ l) :
    l.flatMap (fun x ↦ List.replicate (f x) (g x)) = List.replicate (f x₀) (g x₀)

private theorem divisorCount_cell {n : ℕ} (q : ℚ) (off : ℤ) (a b : ℕ) (ha : a < n) (hb : b < n)
    (v : Fin (n + 1)) :
    (divisorCount off fun ij : Fin n × Fin n ↦
      if ij.1.val = a ∧ ij.2.val = b then v else 0).eval q =
      (falling (availablePoints off (a+1)) v).eval q / ((v : ℕ).factorial : ℚ)

private theorem coeff_otherChildren {n : ℕ} (m : Pattern n) (l : List (ℕ × State))
    (h : (otherChildrenList 1 m).Perm l) (q : ℚ) (σ : FactorType) :
    coeffAt q (childProd (otherChildren 1 m)) σ = coeffAt q (childProd l) σ

private theorem mem_otherChildren {n : ℕ} {a : ℕ} {m : Pattern n} {z : ℕ × State}
    (h : z ∈ otherChildren a m) :
    ∃ ij : Fin n × Fin n, z = (ij.1.val+1, .single a (ij.2.val+1))

private theorem children_eq_singleton (s : State) (hs : s.Valid) (P : TangentPattern s.degree)
    (hP : Allowed s P) (z : ℕ × State) (hz : z ∈ children s P) (heq : z.2.degree = s.degree) :
    children s P = [z] ∧ z.1 = 1

private theorem nonself_child_rank_lt (s : State) (hs : s.Valid) (P : TangentPattern s.degree)
    (hP : Allowed s P) (hself : ¬ SelfPattern s P) (z : ℕ × State) (hz : z ∈ children s P) :
    z.2.rank < s.rank

private theorem stateLaw_single (a c : ℕ) (hs : (State.single a c).Valid) (hc : c ≠ 1) :
    stateLaw (.single a c) =
      lawScale (.inv (.sub (.const 1) (returnWeight c))) (exitLaw (.single a c))

private theorem crossing_one_one_law (a b : ℕ) (ha : 0 < a) (hb : 0 < b) (q : ℚ) (hq : 1 < q)
    (σ : FactorType) :
    coeffAt q (stateLaw (.crossing a b 1 1)) σ = if σ = {(a+b, 1)} then 1 else 0

private theorem crossing_left_one_law (a b h : ℕ) (ha : 0 < a) (hb : 0 < b) (hh : 0 < h) (q : ℚ)
    (hq : 1 < q) (σ : FactorType) :
    coeffAt q (stateLaw (.crossing a b 1 h)) σ = if σ = {(a+h*b, 1)} then 1 else 0

private theorem crossing_right_one_law (a b c : ℕ) (ha : 0 < a) (hb : 0 < b) (hc : 0 < c) (q : ℚ)
    (hq : 1 < q) (σ : FactorType) :
    coeffAt q (stateLaw (.crossing a b c 1)) σ = if σ = {(c*a+b, 1)} then 1 else 0

private theorem children_single_perm {a c : ℕ} (P : TangentPattern (State.single a c).degree)
    {l : List (ℕ × State)}
    (h : ((if P.rt.val = 0 then [] else [(1, State.crossing a a P.rt.val (c - P.d.val))]) ++
      otherChildrenList a P.other).Perm l) : (children (.single a c) P).Perm l

private theorem coeff_m3Quadratic (q : ℚ) (σ : FactorType) :
    coeffAt q (childProd (otherChildren 1 m3Quadratic)) σ =
      if σ = (1,1) ::ₘ {(1,2)} then 1 else 0

private theorem coeff_m3Split (q : ℚ) (σ : FactorType) :
    coeffAt q (childProd (otherChildren 1 m3Split)) σ =
      if σ = (1,1) ::ₘ (1,1) ::ₘ {(1,1)} then 1 else 0

private theorem residuePatterns_four :
    residuePatterns 4 = {m4Split, m4SplitTangent, m4SplitQuadratic, m4ContactThree, m4Cubic,
      m4TwoTangent, m4TangentQuadratic, m4TwoQuadratic, m4QuadraticContact, m4Inert,
      m4Contact}

private theorem single_two_law_at_two (σ : FactorType) : coeffAt 2 (stateLaw (.single 1 2)) σ =
    (if σ = {(2,1)} then 2/3 else 0) + (if σ = (1,1) ::ₘ {(1,1)} then 1/6 else 0) +
      (if σ = {(1,2)} then 1/6 else 0)

private theorem crossing_two_two_law_at_two (σ : FactorType) :
    coeffAt 2 (stateLaw (.crossing 1 1 2 2)) σ = (if σ = {(4,1)} then 1/3 else 0) +
      (if σ = {(2,2)} then 7/12 else 0) + (if σ = (2,1) ::ₘ {(2,1)} then 1/12 else 0)

private theorem coeff_m4SplitQuadratic (q : ℚ) (σ : FactorType) :
    coeffAt q (childProd (otherChildren 1 m4SplitQuadratic)) σ =
      if σ = (1,1) ::ₘ (1,1) ::ₘ {(1,2)} then 1 else 0

private theorem coef_ringHom_ext {F G : Coef →+* Coef}
    (h : ∀ σ g, F (AddMonoidAlgebra.single σ g) = G (AddMonoidAlgebra.single σ g)) (y : Coef) :
    F y = G y

private theorem adamsSer_subst (k : ℕ) (hk : k ≠ 0) (φ : Ser)
    (hφ : PowerSeries.map (adamsCoef k) φ = φ) (f : Ser) (hf : PowerSeries.constantCoeff f = 0) :
    adamsSer k (φ.subst f) = φ.subst (adamsSer k f)

private theorem divisorTransform_inv (a b : ℕ → ℚ) (f : Ser) (hf : PowerSeries.constantCoeff f = 0)
    (hab : ∀ m, ∑ k ∈ m.divisors, a k * b (m / k) = if m = 1 then 1 else 0) :
    divisorTransform a (divisorTransform b f) = f

private theorem moebius_weight_left (m : ℕ) :
    ∑ k ∈ m.divisors, (((ArithmeticFunction.moebius k : ℤ) : ℚ) / (k : ℚ)) * ((m / k : ℕ) : ℚ)⁻¹
      = if m = 1 then 1 else 0

private theorem fraction_sum_pow_var (L : List ℕ) :
    (Expr.sum (L.map fun i ↦ Expr.pow Expr.var i)).fraction
      = ((L.map fun i ↦ (Polynomial.X : Polynomial ℚ) ^ i).sum, 1)

private theorem rational_projectiveNormalizer (n : ℕ) :
    (projectiveNormalizer n).rational =
      ∑ i ∈ Finset.range (n + 1), (RatFunc.X : RatFunc ℚ) ^ i

private theorem scongr_subst (n : ℕ) (a : Ser) (f g : Ser)
    (hf : PowerSeries.constantCoeff f = 0) (hg : PowerSeries.constantCoeff g = 0)
    (h : SCongr n f g) : SCongr n (a.subst f) (a.subst g)

private theorem wf_subst_and_rational_subst (e : Expr) (he : e.wf) (φ : RatFunc ℚ →+* RatFunc ℚ)
    (hX : e.rational = φ RatFunc.X) (x : Expr) (hx : x.wf) :
    (x.subst e).wf ∧ (x.subst e).rational = φ x.rational

private theorem rational_subst_of_wf (e : Expr) (he : e.wf) (φ : RatFunc ℚ →+* RatFunc ℚ)
    (hX : e.rational = φ RatFunc.X) {x : Expr} (hx : x.wf) :
    (x.subst e).rational = φ x.rational

private theorem rational_availablePoints (ε : ℤ) (δ : ℕ) :
    (availablePoints ε δ).rational =
      if δ = 1 then (RatFunc.X : RatFunc ℚ) + (ε : RatFunc ℚ) else (pointCount δ).rational

private theorem X_mul_X_inv_sub_X_zpow_neg_tri (n : ℕ) :
    (RatFunc.X : RatFunc ℚ) * ((RatFunc.X : RatFunc ℚ)⁻¹ - (RatFunc.X : RatFunc ℚ) ^
      (-(tri n : ℤ))) = 1 - (returnWeight n).rational

private theorem plethSum_C_mul_moebiusSum (ε : ℤ) (L : Ser) :
    plethSum (PowerSeries.C (scalar (RatFunc.X + (ε : RatFunc ℚ))) * moebiusSum L) =
        countSum ε L

private theorem lawCoef_stateLaw_crossing_comm (a b c h : ℕ) (ha : 0 < a) (hb : 0 < b) (hc : 0 < c)
    (hh : 0 < h) :
    lawCoef (stateLaw (State.crossing a b c h)) = lawCoef (stateLaw (State.crossing b a h c))

private theorem expSer_sum (s : Finset ℕ) (F : ℕ → Ser)
    (hF : ∀ m ∈ s, PowerSeries.constantCoeff (F m) = 0) :
    expSer (∑ m ∈ s, F m) = ∏ m ∈ s, expSer (F m)

private theorem ratFunc_ringHom_ext (φ ψ : RatFunc ℚ →+* RatFunc ℚ)
    (h : ∀ g : Polynomial ℚ, φ (algebraMap (Polynomial ℚ) (RatFunc ℚ) g)
      = ψ (algebraMap (Polynomial ℚ) (RatFunc ℚ) g)) : φ = ψ

private theorem qmul_eq_sum_range (U V : QSer) (c h : ℕ) :
    qmul U V c h = ∑ a ∈ Finset.range (c + 1), ∑ b ∈ Finset.range (h + 1),
      qpow (-((a : ℤ) * ((h - b : ℕ) : ℤ))) * (U a b * V (c - a) (h - b))

private theorem sum_range_eq_sum_range_ite {M : Type*} [AddCommMonoid M] (f : ℕ → M) (a N : ℕ)
    (haN : a ≤ N) :
    ∑ x ∈ Finset.range (a + 1), f x = ∑ x ∈ Finset.range (N + 1), if x ≤ a then f x else 0

private theorem constantCoeff_formalPow (c : RatFunc ℚ) (g : Ser)
    (hg : PowerSeries.constantCoeff g = 1) :
    PowerSeries.constantCoeff (formalPow c g) = 1

private theorem inv_factorial_mul_multinomial {n k : ℕ} (κ : Fin n → ℕ) (hk : ∑ r, κ r = k) :
    ((k.factorial : ℚ))⁻¹ * (Nat.multinomial Finset.univ κ : ℚ) =
      (∏ r : Fin n, ((Nat.factorial (κ r) : ℕ) : ℚ))⁻¹

private theorem coeff_dilate_recipSer_clusterSer (a m : ℕ) :
    PowerSeries.coeff m (dilate (recipSer (clusterSer a))) =
      qpow (m : ℤ) * recipCoef (PowerSeries.coeff m (clusterSer a))

private theorem gaussPhi_dilate_recipSer_clusterSer (a : ℕ) (ha : 0 < a) :
