private lemma coeff_prod_sum_of_natDegree_le {A ι : Type} [CommRing A] (s : Finset ι) (p : ι → A[X])
    (d : ι → ℕ) (h : ∀ i ∈ s, (p i).natDegree ≤ d i) :
